from phoenix.fgen.routine import Routine
from phoenix.fgen.instruction3 import (
    InstructionGroup,
    GenericInstruction,
    # KeyMapBasedInstruction,
)
from phoenix.fgen.backends.backend_f90_library import LibraryManagerF90


instruction_group = (
    InstructionGroup(
        [
            GenericInstruction(
                src0_key=num + 1,
                trgt_key=10 - num,
                alph_r=1.0,
                alph_i=0.0,
            )
            for num in range(10)
        ]
    )
    .sorted(lambda x: x["trgt_key"])
    .flatten()
)
my_routine_1 = Routine(
    "myroutine",
    itype=None,
    out_dtype=None,
    in_dtypes=[None],
    instruction_group=instruction_group,
)
my_routine_2 = Routine(
    "myotherroutine",
    itype=None,
    out_dtype=None,
    in_dtypes=[None],
    instruction_group=instruction_group,
)
my_routine_3 = Routine(
    "myotherroutine3",
    itype=None,
    out_dtype=None,
    in_dtypes=[None],
    instruction_group=instruction_group,
)
my_routine_4 = Routine(
    "myotherroutine4",
    itype=None,
    out_dtype=None,
    in_dtypes=[None],
    instruction_group=instruction_group,
)
my_routine_5 = Routine(
    "myotherroutine5",
    itype=None,
    out_dtype=None,
    in_dtypes=[None],
    instruction_group=instruction_group,
)
my_routine_6 = Routine(
    "myotherroutine6",
    itype=None,
    out_dtype=None,
    in_dtypes=[None],
    instruction_group=instruction_group,
)
mylib = LibraryManagerF90("mylib")
auxlib = LibraryManagerF90("auxlib")
mylib.append(my_routine_1, implementation="base")
mylib.append(my_routine_1, implementation="offs")
mylib.append(my_routine_1, implementation="list")
auxlib.append(my_routine_2, implementation="base")
auxlib.append(my_routine_2, implementation="offs")
auxlib.append(my_routine_2, implementation="list")
auxlib.append(my_routine_3, implementation="list")
auxlib.append(my_routine_4, implementation="list")
auxlib.append(my_routine_5, implementation="list")
auxlib.append(my_routine_6, implementation="list")

mylib[("myroutine", "base")].add_dependency(auxlib["myotherroutine", "base"])
mylib[("myroutine", "base")].add_dependency(auxlib["myotherroutine3", "list"])
mylib[("myroutine", "base")].add_dependency(auxlib["myotherroutine4", "list"])
mylib[("myroutine", "base")].add_dependency(auxlib["myotherroutine5", "list"])
mylib[("myroutine", "base")].add_dependency(auxlib["myotherroutine6", "list"])
# print(list(mylib.dependencies))
# print(list(mylib.libroutines))

# print(list(mylib.libroutines)[2][1]._constant_arrays)

for cline in mylib.create_source_lines():
    print(cline)
print()
